<script setup>
import { computed, ref } from 'vue'
import { SHOPPING_APP_PAGE_EVENTS, SHOPPING_APP_PAGE_PROPS, localizeAppPage } from './shopping-app-page-contract'
import Shopping29CmMedia from '../Shopping29CmMedia.vue'
import { shopping29cmMediaSource, shopping29cmProductMedia, shopping29cmProductTone } from '../shopping-29cm-media'

const props = defineProps(SHOPPING_APP_PAGE_PROPS)
const emit = defineEmits(SHOPPING_APP_PAGE_EVENTS)
const localize = (zh, en) => localizeAppPage(props.languageBase, zh, en)
const mediaRole = ref('main')
const productSource = (product, role = 'main') => props.productImageUrl(product) || shopping29cmMediaSource(shopping29cmProductMedia(product?.id, role))
const productTone = (product) => shopping29cmProductTone(product?.id)
const productAlt = (product, role = 'main') => props.productDisplayTitle(product) + ' / 29CM ' + role
const mediaOptions = computed(() => [
  { key: 'main', zh: '完整物件', en: 'OBJECT' },
  { key: 'detail', zh: '材质细节', en: 'DETAIL' },
  { key: 'context', zh: '使用场景', en: 'IN LIFE' },
])
const selectedMediaLabel = computed(() => mediaOptions.value.find((item) => item.key === mediaRole.value) || mediaOptions.value[0])
const displayProducts = computed(() => props.products || [])
</script>

<template>
  <main class="cm-pages" :data-page="pageKey" data-testid="shopping-store-specific-page">
    <header class="cm-page-bar"><button type="button" aria-label="Back" @click="emit('back')"><i class="fas fa-arrow-left" aria-hidden="true"></i></button><div><span>29CM / SEOUL</span><strong>{{ serviceLabel || '29CM' }}</strong></div><div><button type="button" aria-label="Orders" @click="emit('open-orders')">ARCHIVE</button><button type="button" data-testid="shopping-page-cart" :aria-label="localize('选品袋', 'Edit bag')" @click="emit('open-cart')">BAG <b v-if="cartQuantity">{{ cartQuantity }}</b></button></div></header>

    <template v-if="pageKey === 'category'">
      <section class="cm-collection-intro"><div><span>ISSUE {{ String(page).padStart(2, '0') }} / COLLECTION</span><h1>{{ category?.label || localize('本期选物', 'Current edit') }}</h1><p>{{ searchQuery ? localize('从当前选物中筛选出的结果。', 'Results selected from the current edit.') : localize('一组被编辑过的物件，需要时间比较，也需要一个清楚的入口。', 'A considered group of objects needs time to compare and a clear entry point.') }}</p></div><aside><b>{{ String(totalCount).padStart(2, '0') }}</b><span>{{ localize('件物件', 'OBJECTS') }}</span></aside></section>
      <form class="cm-collection-search" @submit.prevent="emit('submit-search')"><span>SEARCH /</span><input type="search" :value="searchQuery" :placeholder="localize('品牌、设计师、物件', 'Brand, designer, object')" @input="emit('update:searchQuery', $event.target.value)" /><button type="submit"><i class="fas fa-arrow-right" aria-hidden="true"></i></button></form>
      <nav class="cm-collection-index" :aria-label="localize('分类目录', 'Category index')"><button v-for="item in categories" :key="item.key" type="button" :class="{ 'is-active': item.key === category?.key }" @click="emit('select-category', item.key)"><span>{{ item.label }}</span><small>{{ String(item.count).padStart(2, '0') }}</small></button></nav>
      <div v-if="displayProducts.length === 0" class="cm-page-empty"><Shopping29CmMedia :src="''" alt="" eyebrow="COLLECTION / EMPTY" label="—" tone="paper" role="state" icon="fas fa-compass" /><div><span>{{ searchQuery ? 'SEARCH / 00' : 'INDEX / WAITING' }}</span><h2>{{ searchQuery ? localize('没有匹配结果。', 'No matching objects.') : localize('这一章还没有物件。', 'This chapter has no objects yet.') }}</h2><button type="button" @click="emit('submit-search')">{{ localize('重新整理', 'RESET EDIT') }}</button></div></div>
      <section v-else class="cm-collection-flow"><article v-for="(product, index) in displayProducts" :key="product.id" class="cm-collection-item" :class="{ 'is-lead': index === 0, 'is-offset': index % 3 === 2 }" :data-testid="'shopping-product-' + product.id"><button type="button" class="cm-collection-media" @click="emit('open-product', product.id)"><Shopping29CmMedia :src="productSource(product)" :alt="productAlt(product)" :eyebrow="index === 0 ? 'EDITOR’S PICK' : 'OBJECT ' + String(index + 1).padStart(2, '0')" :label="props.productDisplayTitle(product)" :tone="productTone(product)" icon="fas fa-cube" /></button><div class="cm-collection-copy cm-object-copy"><div class="cm-collection-meta"><span>{{ props.productDisplayTitle(product) }}</span><button type="button" :aria-label="localize('收藏或取消收藏', 'Toggle favorite')" :class="{ 'is-favorite': props.isProductFavorite(product.id) }" @click="emit('toggle-favorite', product.id)"><i class="fas fa-heart" aria-hidden="true"></i></button></div><button type="button" class="cm-object-title" @click="emit('open-product', product.id)">{{ props.productDisplayTitle(product) }}</button><p>{{ props.productDisplayDescription(product) }}</p><strong>{{ props.formatPrice(product) }}</strong><div><button type="button" class="cm-read-link" @click="emit('open-product', product.id)">{{ localize('查看详情', 'READ OBJECT') }} <i class="fas fa-arrow-right" aria-hidden="true"></i></button><button type="button" class="cm-quick-add" :disabled="product.stockStatus === 'sold_out'" :data-testid="'shopping-add-cart-' + product.id" @click="emit('add-to-cart', product.id)">{{ localize('加入袋', 'ADD') }}</button></div></div></article></section>
      <nav v-if="pageCount > 1" class="cm-page-nav" data-testid="shopping-pagination"><button type="button" :disabled="page <= 1" @click="emit('change-page', page - 1)">← {{ localize('上一章', 'PREVIOUS') }}</button><span>{{ String(page).padStart(2, '0') }} / {{ String(pageCount).padStart(2, '0') }}</span><button type="button" :disabled="page >= pageCount" @click="emit('change-page', page + 1)">{{ localize('下一章', 'NEXT') }} →</button></nav>
    </template>

    <template v-else-if="product">
      <section class="cm-pdp-intro"><div class="cm-pdp-media"><Shopping29CmMedia :src="productSource(product, mediaRole)" :alt="productAlt(product, mediaRole)" :eyebrow="selectedMediaLabel.en" :label="props.productDisplayTitle(product)" :tone="productTone(product)" :role="mediaRole === 'context' ? 'context' : 'object'" icon="fas fa-cube" /><div class="cm-pdp-media-tabs"><button v-for="item in mediaOptions" :key="item.key" type="button" :class="{ 'is-active': mediaRole === item.key }" @click="mediaRole = item.key"><span>{{ item.en }}</span><small>{{ localize(item.zh, item.en) }}</small></button></div></div><div class="cm-pdp-copy"><span class="cm-pdp-kicker">29CM / OBJECT DOSSIER</span><h1>{{ props.productDisplayTitle(product) }}</h1><blockquote>{{ localize('一件值得靠近、使用，再留下来的物件。', 'An object worth approaching, using, and keeping.') }}</blockquote><p>{{ props.productDisplayDescription(product) }}</p><div class="cm-pdp-facts"><span><small>{{ localize('状态', 'STATUS') }}</small><b>{{ props.stockStatusLabel(product.stockStatus) }}</b></span><span><small>{{ localize('归属', 'EDIT') }}</small><b>{{ serviceLabel || '29CM' }}</b></span></div><strong class="cm-pdp-price">{{ props.formatPrice(product) }}</strong><div class="cm-pdp-actions"><button type="button" :class="{ 'is-saved': props.isProductFavorite(product.id) }" @click="emit('toggle-favorite', product.id)"><i class="fas fa-heart" aria-hidden="true"></i>{{ localize('保存', 'SAVE') }}</button><button type="button" data-testid="shopping-product-add" :disabled="product.stockStatus === 'sold_out'" @click="emit('add-to-cart', product.id, 1)">{{ product.stockStatus === 'sold_out' ? localize('暂时售罄', 'SOLD OUT') : localize('加入选品袋', 'ADD TO BAG') }} <i class="fas fa-arrow-right" aria-hidden="true"></i></button></div></div></section>
      <section class="cm-pdp-note"><header><span>01</span><p>EDITOR’S NOTE</p></header><div><h2>{{ localize('使用的时间越长，选择越清楚。', 'The longer it is used, the clearer the choice becomes.') }}</h2><p>{{ localize('编辑关注触感、比例、收纳方式与每天真正使用它的频率。这里不急着销售，而是把选择的理由完整留下。', 'The edit considers tactility, proportion, storage, and how often the object will truly be used. The reason for choosing it comes before the sale.') }}</p></div></section>
      <section class="cm-pdp-detail"><div><span>02 / MATERIAL</span><h2>{{ localize('材料会决定它如何进入生活。', 'Material decides how it enters life.') }}</h2><p>{{ localize('以下内容只描述可观察的触感与维护方向；规格、价格与库存始终由页面代码表达。', 'This section describes observable tactility and care. Specifications, price, and stock remain code-rendered.') }}</p></div><Shopping29CmMedia :src="productSource(product, 'detail')" :alt="productAlt(product, 'detail')" eyebrow="MATERIAL / DETAIL" label="02" :tone="productTone(product)" role="material" icon="fas fa-grip-lines" /></section>
      <section class="cm-pdp-context"><Shopping29CmMedia :src="productSource(product, 'context')" :alt="productAlt(product, 'context')" eyebrow="OBJECTS IN USE" label="03" :tone="productTone(product)" role="context" icon="fas fa-table-cells-large" /><div><span>03 / IN LIFE</span><h2>{{ localize('不是展示它，而是想象它被反复使用。', 'Not displayed. Repeatedly used.') }}</h2><p>{{ localize('场景图只帮助理解尺度、位置与相邻物件，不承诺超出订单事实的生活方式。', 'The context image clarifies scale, placement, and neighboring objects without promising a lifestyle beyond the order facts.') }}</p></div></section>
      <section class="cm-pdp-care"><div><span>04 / CARE</span><h2>{{ localize('留下它，也照顾它。', 'Keep it, then care for it.') }}</h2></div><dl><div><dt>{{ localize('清洁', 'CLEAN') }}</dt><dd>{{ localize('以柔软干布处理表面灰尘。', 'Use a soft dry cloth for surface dust.') }}</dd></div><div><dt>{{ localize('收纳', 'STORE') }}</dt><dd>{{ localize('避免长时间潮湿与强光直射。', 'Avoid prolonged moisture and direct harsh light.') }}</dd></div><div><dt>{{ localize('记录', 'ARCHIVE') }}</dt><dd>{{ localize('购买与配送记录会在档案中保留。', 'Purchase and delivery records remain in the Archive.') }}</dd></div></dl></section>
      <section v-if="relatedProducts.length" class="cm-related"><header><span>05 / RELATED OBJECTS</span><h2>{{ localize('同一套生活语法', 'The same daily grammar') }}</h2></header><div><button v-for="related in relatedProducts.slice(0, 4)" :key="related.id" type="button" @click="emit('open-product', related.id)"><Shopping29CmMedia :src="productSource(related)" :alt="productAlt(related)" :eyebrow="'RELATED'" label="+" :tone="productTone(related)" icon="fas fa-cube" /><strong>{{ props.productDisplayTitle(related) }}</strong><small>{{ props.formatPrice(related) }}</small></button></div></section>
    </template>
  </main>
</template>
